queries.query:
find view "view:pipeline:step_execution" s
| filter s.start_ts >= cast(${start_time} as timestamp) and s.start_ts <= cast(${end_time} as timestamp)
| filter s.step_type in ["HarnessApproval", "JiraApproval", "ServiceNowApproval", "CustomApproval"]
| filter ${project_filter_predicate}
| aggregate { distinct_count(s.step_execution_id) as approval_steps }

find view "view:pipeline:step_execution" s
| filter s.start_ts >= cast(${start_time} as timestamp) and s.start_ts <= cast(${end_time} as timestamp)
| filter s.step_type in ["HarnessApproval", "JiraApproval", "ServiceNowApproval", "CustomApproval"]
| filter ${project_filter_predicate}
| filter s.duration > 0
| aggregate { avg(s.duration) / 1000.0 as avg_wait_s }

find view "view:pipeline:step_execution" s
| filter s.start_ts >= cast(${start_time} as timestamp) and s.start_ts <= cast(${end_time} as timestamp)
| filter s.step_type in ["HarnessApproval", "JiraApproval", "ServiceNowApproval", "CustomApproval"]
| filter ${project_filter_predicate}
| aggregate { count(case when s.status in ["REJECTED", "APPROVAL_REJECTED", "EXPIRED", "ABORTED", "FAILED"] then 1 end) as not_approved }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { distinct_count(d.stage_execution_id) as changes }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) as failed_changes }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count(case when d.is_automated_rollback = true or d.rollback_duration > 0 then 1 end) as rollbacks }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { 100.0 * count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) / nullif(count(), 0) as failed_change_rate }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    case when date_diff(date_trunc("week", d.start_ts), d.start_ts, "day") < 1 then "1 Mon" when date_diff(date_trunc("week", d.start_ts), d.start_ts, "day") < 2 then "2 Tue" when date_diff(date_trunc("week", d.start_ts), d.start_ts, "day") < 3 then "3 Wed"
         when date_diff(date_trunc("week", d.start_ts), d.start_ts, "day") < 4 then "4 Thu" when date_diff(date_trunc("week", d.start_ts), d.start_ts, "day") < 5 then "5 Fri" when date_diff(date_trunc("week", d.start_ts), d.start_ts, "day") < 6 then "6 Sat"
         else "7 Sun" end as weekday,
    case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then "Failed" else "Succeeded" end as outcome,
    distinct_count(d.stage_execution_id) as changes
  }
| group_by weekday, outcome
| order_by weekday asc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    cast(date_diff(date_trunc("day", d.start_ts), d.start_ts, "hour") as int) as hour_utc,
    distinct_count(d.stage_execution_id) as changes
  }
| group_by hour_utc
| order_by hour_utc asc

find view "cd:view:runtime_inputs_info" r
| filter r.row_created_at >= cast(${start_time} as timestamp) and r.row_created_at <= cast(${end_time} as timestamp)
| filter ${project_filter_predicate}
| aggregate {
    r.display_name as runtime_input,
    distinct_count(r.plan_execution_id) as executions
  }
| group_by runtime_input
| order_by executions desc
| limit 15
